{
  "shot": {
    "composition": "中景镜头，焦距 50mm，使用 Sony Venice 摄像机，浅景深，焦点精确对准主体面部与手中橙子，背景果树模糊形成自然虚化",
    "camera_motion": "静态镜头，无运镜，轻微微调对焦以捕捉面部表情与橙子细节"
  },
  "subject": {
    "description": "一位 55 岁的东亚男性，面部有岁月痕迹与皱纹，眼神温和而专注，嘴角微扬，留有短而灰白的头发，面部轮廓清晰，皮肤略显粗糙，显示出长期户外劳作的痕迹，身材中等偏瘦，肌肉线条自然，双手粗糙有力，指甲修剪整齐，掌心托着橙子，展现出劳动者的朴实与坚韧",
    "wardrobe": "灰色与深蓝色拼接的工装夹克，内搭深色衬衫，夹克袖口与下摆有磨损痕迹，材质为耐磨防风面料，左胸口袋有红色品牌标识，整体服装朴素实用，符合果园劳作场景"
  },
  "scene": {
    "location": "中国南方丘陵地带的柑橘果园，果树密集，枝叶繁茂，地面覆盖落叶与泥土，远处可见其他果树与稀疏的田埂",
    "time_of_day": "上午 10:00，阳光充足但不刺眼，光线柔和",
    "environment": "果园内空气清新，树叶随微风轻晃，背景中橙子挂满枝头，色彩鲜艳，地面有零星落叶与泥土，右侧可见一个白色编织篮，内装部分采摘的橙子，整体环境充满丰收的喜悦与自然的宁静"
  },
  "visual_details": {
    "action": "老人双手捧着一簇橙子，面向镜头微笑，眼神充满自豪与满足，橙子表面光滑，色泽鲜亮，呈现出自然的橙黄色，背景果树在微风中轻轻摇曳",
    "props": "橙子、白色编织篮、果树枝叶、落叶与泥土",
    "action_sequence": [
      "老人双手捧起一簇橙子，橙子堆叠成金字塔状，表面反射柔和阳光",
      "老人微微抬头，目光直视镜头，嘴角上扬，露出温和的笑容",
      "背景果树在微风中轻轻摇曳，橙子随风轻晃，增添动态感",
      "镜头轻微聚焦于橙子表面，捕捉其光滑质感与自然光泽",
      "老人保持微笑，双手稳稳托住橙子，展现出丰收的满足与自豪"
    ]
  },
  "cinematography": {
    "lighting": "自然光为主，阳光从左上方斜射，柔和地照亮老人面部与橙子表面，形成温暖的高光与柔和阴影，背景树叶被阳光穿透，形成斑驳光影，增强画面层次感",
    "tone": "纪实真实感，温暖、宁静、充满丰收喜悦与乡土情怀，略带人文关怀与自然和谐的氛围"
  }
}
